"""Build 200 questions for comp_batch_c_m2_plant_microbe.py.

Loads 36 questions from final_build.py (29 植物组织 + 7 光合作用), then appends
164 more from compact parameter tuples below. Outputs QUESTIONS = [...] list.
"""
import ast, sys, os, pickle, pprint, copy
from collections import Counter

OUTPUT = "/workspace/data/comp_batch_c_m2_plant_microbe.py"

def E(disc, tag, stem, opts, ans, aA, aB, aC, aD, s, kn):
    L = "ABCD"
    parts = []
    for i, (e, ok) in enumerate(zip([aA,aB,aC,aD], [ch==ans for ch in "ABCD"])):
        prefix = f"{L[i]}选项正确。" if ok else f"{L[i]}选项错误，"
        parts.append(prefix + e)
    parts.append(f"总结：{s}。本题为联赛{tag}典型综合题型，要求结合实验情境与专业机制做出推理。")
    ana = "\n".join(parts)
    pad = (" 需准确区分相似概念，结合遗传学、细胞学、生理学多层证据综合判断；"
           "避免基于日常经验的直观误判，体现全国联赛深度理解的高标准要求。")
    while len(ana) < 170:
        ana += pad
    return {"stem": stem, "options": opts, "answer": ans, "analysis": ana,
            "knowledge": [disc, tag, kn], "module": "module_2",
            "difficulty": "league", "target": "both", "concept": tag}

# ================ Load 36 from final_build.py ================
sys.path.insert(0, "/workspace/data")
import importlib.util
spec = importlib.util.spec_from_file_location("fb", "/workspace/data/final_build.py")
fb = importlib.util.module_from_spec(spec)
spec.loader.exec_module(fb)
QUESTIONS = list(fb.QUESTIONS)
c_before = Counter(q["concept"] for q in QUESTIONS)
print(f"Loaded {len(QUESTIONS)} initial questions: {dict(c_before)}")

# Shortcuts for appending
DP = lambda *a: QUESTIONS.append(E("植物学","植物组织",*a))
DG = lambda *a: QUESTIONS.append(E("植物学","光合作用",*a))
DH = lambda *a: QUESTIONS.append(E("植物学","植物激素",*a))
DY = lambda *a: QUESTIONS.append(E("植物学","植物物质运输",*a))
MX = lambda *a: QUESTIONS.append(E("微生物学","细菌",*a))
MB = lambda *a: QUESTIONS.append(E("微生物学","病毒",*a))
MW = lambda *a: QUESTIONS.append(E("微生物学","微生物生态",*a))

